mapper.insert:
insert
ignore into corgi_user_recommend(user_id, rec_user_id)
values(
#{userId},
#{recId}
)

mapper.update:
update corgi_user_recommend
set `weight` = `weight` + #{weight}
where user_id = #{userId}
  and rec_user_id = #{recId}

update corgi_user_recommend
set `status` = #{status},
    opt_time = #{opt}
where user_id = #{userId}
  and rec_user_id = #{recId}

mapper.select:
select r.rec_user_id         userId
from corgi_user_recommend r
where r.user_id = #{userId}
  and r.`status` = '0'
  and not exists (select 1 from corgi_user_follow f where f.user_id = #{userId}
  and f.follow_user_id = r.rec_user_id)
  and exists (select 1 from corgi_vlog v where v.user_id = r.rec_user_id)
  and r.rec_user_id != #{userId}
order by r.`weight` desc
    limit #{size}

select d.user_id userId, d.nickname `nickname`, d.avatar avatar, d.avatar_status avatarStatus, d.avatar_check_status avatarCheckStatus, d.role role, d.hide_role hideRole, d.group `group`, d.hide_group `hideGroup`, d.hide_prefer_group `hidePreferGroup`, d.con con, d.relation, d.check_status checkStatus, d.weight, d.height, d.birthday, p.uptime time from corgi_influencer_billboard b left join corgi_user_detail d on d.user_id = b.user_id left join corgi_user_position p on p.user_id = b.user_id where b.city = #{city}
and d.user_id != #{userId} and not exists(select 1 from corgi_user_follow f where f.user_id = #{userId} and f.follow_user_id = d.user_id) and not exists(select 1 from corgi_user_recommend r where r.user_id = #{userId} and r.rec_user_id = d.user_id and r.status = '2')
and d.user_id != '8' order by b.fan desc limit #{size}

select d.user_id userId, d.nickname `nickname`, d.avatar avatar, d.avatar_status avatarStatus, d.avatar_check_status avatarCheckStatus, d.role role, d.hide_role hideRole, d.group `group`, d.hide_group `hideGroup`, d.hide_prefer_group `hidePreferGroup`, d.con con, d.relation, d.check_status checkStatus, d.weight, d.height, d.birthday from corgi_influencer_billboard b left join corgi_user_detail d on d.user_id = b.user_id where b.city != #{city}
and d.user_id != #{userId} and not exists(select 1 from corgi_user_follow f where f.user_id = #{userId} and f.follow_user_id = d.user_id) and not exists(select 1 from corgi_user_recommend r where r.user_id = #{userId} and r.rec_user_id = d.user_id and r.status = '2')
and d.user_id != '8' order by b.fan desc limit #{size}

select d.user_id userId, d.nickname `nickname`, d.avatar avatar, d.avatar_status avatarStatus, d.avatar_check_status avatarCheckStatus, d.role role, d.hide_role hideRole, d.group `group`, d.hide_group `hideGroup`, d.hide_prefer_group `hidePreferGroup`, d.con con, d.relation, d.check_status checkStatus, d.weight, d.height, d.birthday, count(1) isFollowed from corgi_user_detail d join corgi_user_position p on p.user_id = d.user_id left join corgi_user_follow f on d.user_id = f.follow_user_id and is_deleted = '0' where and p.city = #{city}
and d.user_id != #{userId} and not exists(select 1 from corgi_user_follow f where f.user_id = #{userId} and f.follow_user_id = d.user_id) and not exists(select 1 from corgi_user_recommend r where r.user_id = #{userId} and r.rec_user_id = d.user_id and r.status = '2')
and d.avatar_status != 'influencer' group by d.user_id order by isFollowed desc limit #{start}, #{size}

mapper.delete:
delete
from corgi_user_recommend
where user_id = #{userId}
  and `weight` <= #{weight}
  and `status` = '0'
